"""Works cards on the home page: stickers pop on hover (Triceratops) and the Linguistics card becomes
the same hover collage as its case study banner. Used by tools/convert_export.py and run once on index.html."""
import re

STAR = '<svg viewBox="0 0 24 24"><path d="M12 0C13 8 16 11 24 12C16 13 13 16 12 24C11 16 8 13 0 12C8 11 11 8 12 0Z"/></svg>'
SPARKS = [(7, 16, 30, 0, 3.2), (12, 70, 20, 1.1, 2.8), (90, 20, 26, .6, 3.8), (93, 62, 18, 1.8, 3.0), (80, 82, 14, .3, 2.6)]
LC_CARD = ('<div class="wc-lc" style="position: relative; margin: 12px; min-height: 260px; border-radius: var(--radius-md); overflow: hidden; box-shadow: inset 0 0 0 2px #00000022;">\n'
    '            <div class="lc-sky" aria-hidden="true">'
    + ''.join(f'<span class="lc-spark" style="left:{x}%;top:{y}%;--s:{sz}px;--d:{d}s;--t:{t}s">{STAR}</span>' for x, y, sz, d, t in SPARKS)
    + '</div>\n'
    '            <div class="wc-lc-laptop"><div class="wc-lc-lid"><span class="wc-lc-cam" aria-hidden="true"></span><img src="assets/images/lc-final-search.webp" alt="The final Linguistics Club Undergraduate Programs page with program search and filters" loading="lazy"></div><div class="wc-lc-base" aria-hidden="true"><span></span></div></div>\n'
    '            <figure class="lc-mini lc-detail" aria-hidden="true"><img src="assets/images/lc-final-save-visit.webp" alt="" loading="lazy"></figure>\n'
    '            <figure class="lc-mini lc-mail" aria-hidden="true"><img src="assets/images/lc-final-mailing-list.webp" alt="" loading="lazy"></figure>\n'
    '            <img class="lc-wug" aria-hidden="true" alt="" src="assets/images/wug.png" loading="lazy">\n'
    '          </div>')

CSS = '''
/* Works cards: the Triceratops stickers pop and the Linguistics collage tilts in on hover, matching each case study's banner */
.wc-sticker{transition:translate .35s cubic-bezier(.3,1.6,.5,1),scale .35s cubic-bezier(.3,1.6,.5,1),filter .35s ease}
.workcard:hover .wc-sticker{translate:0 -10px;scale:1.12;filter:drop-shadow(0 12px 12px rgba(30,40,60,.3))!important}
.wc-lc{background:linear-gradient(160deg,#f1eefe,#d4cff7 50%,#ab9fe8)}
.wc-lc .lc-sky{position:absolute;inset:0;pointer-events:none}
.wc-lc .lc-spark{position:absolute;width:var(--s);height:var(--s);margin:calc(var(--s) / -2) 0 0 calc(var(--s) / -2);animation:lcTwinkle var(--t) ease-in-out var(--d) infinite}
.wc-lc .lc-spark svg{display:block;width:100%;height:100%;fill:#fff;filter:drop-shadow(0 0 6px #fff) drop-shadow(0 0 2px #8f84e0)}
@keyframes lcTwinkle{0%,100%{transform:scale(.55) rotate(0);opacity:.35}50%{transform:scale(1) rotate(45deg);opacity:1}}
.wc-lc{display:flex;align-items:center;justify-content:center;padding:26px 26px 34px}
.wc-lc-laptop{position:relative;z-index:1;width:82%;display:flex;flex-direction:column;align-items:center}
.wc-lc-lid{position:relative;width:100%;padding:9px 9px 14px;box-sizing:border-box;border-radius:14px 14px 4px 4px;background:linear-gradient(180deg,#1d1d22,#0b0b0e);box-shadow:inset 0 0 0 1px #3a3a42,0 18px 30px rgba(40,30,110,.4)}
.wc-lc-cam{position:absolute;top:3px;left:50%;width:5px;height:5px;margin-left:-2.5px;border-radius:50%;background:#2c2c34;box-shadow:inset 0 0 0 1px #45454f}
.wc-lc-lid img{display:block;width:100%;height:auto;aspect-ratio:1100/620;object-fit:cover;object-position:top;border-radius:3px}
.wc-lc-base{position:relative;width:114%;height:12px;border-radius:2px 2px 12px 12px;background:linear-gradient(180deg,#3a3a42 0,#1a1a1f 45%,#0b0b0e 100%);box-shadow:0 10px 18px rgba(40,30,110,.35)}
.wc-lc-base span{position:absolute;top:0;left:50%;width:16%;height:5px;margin-left:-8%;border-radius:0 0 6px 6px;background:#0e0e12}
.wc-lc .lc-mini,.wc-lc .lc-wug{position:absolute;transition:transform .55s cubic-bezier(.2,.9,.25,1.15),opacity .35s ease}
.wc-lc .lc-mini{z-index:3;margin:0;border-radius:8px;overflow:hidden;background:#fff;box-shadow:0 0 0 2px #fff,0 12px 24px rgba(70,50,150,.3);opacity:0}
.wc-lc .lc-mini img{display:block;width:100%;height:auto}
.wc-lc .lc-detail{left:3%;bottom:8%;width:34%;transform:translate(-70%,25%) rotate(-14deg)}
.wc-lc .lc-mail{right:3%;top:6%;width:24%;transform:translate(70%,-20%) rotate(14deg)}
.wc-lc .lc-wug{z-index:4;right:2%;bottom:0;width:24%;height:auto;transform:translateY(105%)}
.workcard:hover .wc-lc .lc-mini{opacity:1}
.workcard:hover .wc-lc .lc-detail{transform:rotate(-4deg)}
.workcard:hover .wc-lc .lc-mail{transform:rotate(4deg);transition-delay:.08s}
.workcard:hover .wc-lc .lc-wug{transform:none;transition-delay:.15s}
@media (prefers-reduced-motion:reduce){.wc-sticker,.wc-lc .lc-mini,.wc-lc .lc-wug{transition:opacity .2s}.wc-lc .lc-spark{animation:none}}
'''

GOOGLE_CARD = '<article class="pp-frame rv workcard wc-soon" style="display: flex; flex-direction: column;">\n        <div class="cardlink" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); color: var(--ink);">\n          <div class="wc-yt" role="img" aria-label="Illustration: an affinity map of sticky notes around a wireframe of a careers page with a video, under a Coming soon sign" style="position: relative; margin: 12px; min-height: 260px; border-radius: var(--radius-md); overflow: hidden; box-shadow: inset 0 0 0 2px #00000022;">\n            <div class="yt-notes" aria-hidden="true"><span class="yt-note" style="left:6%;top:14%;--c:#fff3a6;--r:-6deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:17%;top:9%;--c:#fff3a6;--r:4deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:8%;top:38%;--c:#ffd1e3;--r:3deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:19%;top:33%;--c:#ffd1e3;--r:-5deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:6%;top:62%;--c:#cdeebd;--r:-3deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:18%;top:58%;--c:#cdeebd;--r:6deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:76%;top:12%;--c:#cfe4ff;--r:5deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:87%;top:17%;--c:#cfe4ff;--r:-4deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:77%;top:40%;--c:#fff3a6;--r:-6deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:88%;top:44%;--c:#ffd1e3;--r:4deg"><i></i><i></i><i></i></span><span class="yt-note" style="left:80%;top:66%;--c:#cdeebd;--r:3deg"><i></i><i></i><i></i></span></div>\n            <div class="yt-win" aria-hidden="true">\n              <div class="yt-bar"><span></span><span></span><span></span></div>\n              <div class="yt-page">\n                <div class="yt-head"><span class="yt-logo"><svg viewBox="0 0 10 7" shape-rendering="crispEdges"><path fill="#e5332a" d="M1 0h8v1h1v5h-1v1H1v-1H0V1h1z"/><path fill="#fff" d="M4 2h1v1h1v1H5v1H4z"/></svg></span><b></b><b class="s"></b></div>\n                <div class="yt-video"><svg viewBox="0 0 10 7" shape-rendering="crispEdges"><path fill="#e5332a" d="M1 0h8v1h1v5h-1v1H1v-1H0V1h1z"/><path fill="#fff" d="M4 2h1v1h1v1H5v1H4z"/></svg></div>\n                <div class="yt-roles"><span></span><span></span><span></span></div>\n              </div>\n            </div>\n            <div class="yt-sign" aria-hidden="true"><i></i><i></i><span>Coming soon</span></div>\n          </div>\n          <div style="padding: 24px 28px 28px; display: flex; flex-direction: column; gap: 14px;">\n            <h3 style="margin: 0; font-family: var(--font-display); font-size: 31px; line-height: 38px; font-weight: 700;">Helping candidates find their place at YouTube</h3>\n            <p style="margin: 0; font-size: 14px; line-height: 22px; font-weight: 600; color: var(--ink-muted);">Google · YouTube Careers · UX Researcher Intern · Oct 2026 – Present</p>\n            <p style="margin: 0; font-size: 16px; line-height: 26px; color: var(--ink-muted);">Segmented YouTube Careers visitors into 3 candidate cohorts through surveys, and interviewed recruiters and job seekers to shape a candidate profile feature that draws high-profile talent.</p>\n            <div style="display: flex; flex-wrap: wrap; gap: 8px;"><span class="pp-sticker">Mixed-Methods Research</span><span class="pp-sticker">User Segmentation</span><span class="pp-sticker">B2C Candidate Experience</span></div>\n            <div style="display: flex; flex-wrap: wrap; align-items: center; gap: 18px; margin-top: auto; padding-top: 4px;">\n              <span class="readcs soon">Case study coming soon</span>\n            </div>\n          </div>\n        </div>\n      </article>'
CSS += '\n/* Works card: Google / YouTube Careers, coming soon (not a link yet) */\n.wc-soon,.wc-soon *{cursor:default!important}\n.wc-yt{background:#f3e3c3 repeating-linear-gradient(0deg,transparent 0 23px,#00000008 23px 24px),repeating-linear-gradient(90deg,transparent 0 23px,#00000008 23px 24px)}\n.yt-note{position:absolute;left:0;top:0;width:13%;max-width:58px;aspect-ratio:1;background:var(--c);rotate:var(--r);box-shadow:0 0 0 2px #5e2f1833,2px 3px 0 #5e2f1826;padding:6px 5px;display:flex;flex-direction:column;gap:4px;transition:translate .25s steps(3)}\n.yt-note i{display:block;height:3px;background:#3a1f1755}.yt-note i:nth-child(2){width:75%}.yt-note i:nth-child(3){width:55%}\n.workcard:hover .yt-note:nth-child(odd){translate:0 -4px}\n.yt-win{position:absolute;left:25%;right:25%;top:12%;bottom:-6%;background:#fff;border-radius:10px 10px 0 0;box-shadow:0 0 0 3px #2b1f17,0 18px 30px rgba(60,30,20,.3);overflow:hidden;display:flex;flex-direction:column}\n.yt-bar{display:flex;gap:5px;padding:8px 10px;background:#ecd29a;box-shadow:inset 0 -3px 0 #2b1f17}.yt-bar span{width:8px;height:8px;background:#5e2f18}\n.yt-page{flex:1;padding:44px 10px 10px;display:flex;flex-direction:column;gap:9px}\n.yt-head{display:flex;align-items:center;gap:6px}.yt-logo svg{display:block;width:22px;height:16px}\n.yt-head b{height:6px;width:38%;background:#3a1f17}.yt-head b.s{width:18%;margin-left:auto;background:#e5332a}\n.yt-video{flex:1;min-height:70px;background:#2b1f17;display:grid;place-items:center;box-shadow:inset 0 0 0 4px #3a2a20}\n.yt-video svg{width:42px;height:30px;transition:scale .25s steps(3)}.workcard:hover .yt-video svg{scale:1.15}\n.yt-roles{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.yt-roles span{height:22px;background:#fdf1d3;box-shadow:inset 0 0 0 2px #e09a52}\n.yt-sign{position:absolute;left:50%;top:15%;translate:-50% 0;rotate:-4deg;z-index:2;transform-origin:50% -30px;transition:rotate .3s steps(4)}\n.workcard:hover .yt-sign{rotate:3deg}\n.yt-sign i{position:absolute;top:-26px;width:3px;height:28px;background:#5e2f18}.yt-sign i:first-child{left:22%}.yt-sign i:nth-child(2){right:22%}\n.yt-sign span{display:block;padding:8px 18px 6px;background:#a0522a repeating-linear-gradient(0deg,transparent 0 9px,#5e2f1840 9px 11px);color:#fdf1d3;font-family:var(--font-pixel);font-size:24px;line-height:24px;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap;box-shadow:0 0 0 3px #3a1f17,4px 5px 0 #3a1f1740}\n.readcs.soon{color:var(--ink-muted);border-bottom:0}\n.wc-soon h3{font-variant-ligatures:none;font-feature-settings:"liga" 0}\n@media (prefers-reduced-motion:reduce){.yt-note,.yt-sign,.yt-video svg{transition:none}}\n'

def apply(tpl):
    tpl, n = re.subn(r'<img aria-hidden="true" alt="" src="assets/images/sticker-triceratops-', '<img class="wc-sticker" aria-hidden="true" alt="" src="assets/images/sticker-triceratops-', tpl)
    assert n == 4, n
    start = tpl.index('<div style="position: relative; margin: 12px; min-height: 260px; border-radius: var(--radius-md); background: radial-gradient(circle at 50% 48%')
    end = tpl.index('<div style="padding: 24px 28px 28px;', start)
    end = tpl.rindex('          </div>\n', start, end)
    tpl = tpl[:start] + LC_CARD + '\n' + tpl[end + len('          </div>\n'):]
    anchor = '      </article></div>\n    </section>'
    if 'wc-soon' not in tpl and anchor in tpl:
        tpl = tpl.replace(anchor, '      </article>' + GOOGLE_CARD + '</div>\n    </section>', 1)
    return tpl
